export const appShellCss = "/* Infinitum app shell — one layout for every product app.\n   Source of truth: RULES/BUILD_RULES.md and RULES/brand/infinitum.css.\n   Canonical copy: infinitum-nexus/packages/ui/app-shell.css. Apps and standalone\n   repos vendor an identical copy; do not edit a copy, edit this file and re-sync.\n\n   Rules: white paper, ink text, the system Helvetica stack, weight-400 headings,\n   hairline rules. No gradients, shadows, glows or decorative color. The accent\n   is for focus and hover only. Each app shows its own product wordmark with\n   <sup class=\"tm\">™</sup>, never the Infinitum logo. */\n\n:root {\n  --paper: #ffffff;\n  --ink: #111820;\n  --muted: #52606b;\n  --line: #d6dce1;\n  --accent: #2454dd;\n  --ease: cubic-bezier(.22, 1, .36, 1);\n\n  --font: 'Helvetica Neue', Helvetica, Arial, sans-serif;\n  --gutter: 24px;\n  --bar-height: 64px;\n  --column: 1120px;\n  --control-height: 40px;\n\n  /* Type scale */\n  --text-sm: 13px;\n  --text: 16px;\n  --text-lg: 20px;\n  --title: clamp(32px, 4.2vw, 56px);\n  --heading: clamp(24px, 2.6vw, 32px);\n\n  color-scheme: light;\n}\n\n*, *::before, *::after { box-sizing: border-box; }\n\nhtml { -webkit-text-size-adjust: 100%; }\n\nbody {\n  margin: 0;\n  color: var(--ink);\n  background: var(--paper);\n  font-family: var(--font);\n  font-size: var(--text);\n  line-height: 1.55;\n  -webkit-font-smoothing: antialiased;\n}\n\nbutton, input, select, textarea { font: inherit; color: inherit; }\n\n:where(h1, h2, h3, h4) { font-weight: 400; margin: 0 0 .5em; }\n:where(h1) { font-size: var(--title); line-height: 1.02; letter-spacing: -.055em; }\n:where(h2) { font-size: var(--heading); line-height: 1.1; letter-spacing: -.04em; }\n:where(h3) { font-size: var(--text-lg); line-height: 1.25; letter-spacing: -.02em; }\n:where(p) { margin: 0 0 1em; }\n\na { color: inherit; }\na:hover { color: var(--accent); }\n\n/* Focus: 2px accent, 5px offset */\na:focus-visible, button:focus-visible, summary:focus-visible, input:focus-visible,\nselect:focus-visible, textarea:focus-visible, [tabindex]:focus-visible {\n  outline: 2px solid var(--accent);\n  outline-offset: 5px;\n}\n\n/* Skip link */\n.skip-link { position: fixed; top: -100px; left: 20px; z-index: 1000; background: var(--paper); color: var(--ink); padding: 12px; }\n.skip-link:focus { top: 10px; }\n\n/* Trademark: exact size and position from the live site */\nsup.tm { font-size: .38em; vertical-align: super; line-height: 0; margin-left: .08em; letter-spacing: 0; font-weight: 400; }\n.app-wordmark .tm { font-size: .5em; }\n.muted .tm, .app-footer .tm, .app-nav .tm, small .tm { font-size: .65em; }\n\n/* ---------- Shell ---------- */\n\n.app-bar {\n  position: sticky;\n  top: 0;\n  z-index: 50;\n  display: flex;\n  align-items: center;\n  gap: 32px;\n  min-height: var(--bar-height);\n  padding: 0 var(--gutter);\n  background: var(--paper);\n  border-bottom: 1px solid var(--line);\n}\n\n.app-wordmark {\n  flex: none;\n  font-size: 22px;\n  line-height: 1;\n  letter-spacing: -.04em;\n  font-weight: 400;\n  color: var(--ink);\n  text-decoration: none;\n  white-space: nowrap;\n}\n.app-wordmark:hover { color: var(--ink); }\n\n.app-nav {\n  display: flex;\n  align-items: center;\n  gap: 24px;\n  min-width: 0;\n  overflow-x: auto;\n  scrollbar-width: none;\n}\n.app-nav::-webkit-scrollbar { display: none; }\n.app-nav a, .app-nav button {\n  flex: none;\n  padding: 21px 0 20px;\n  border: 0;\n  border-bottom: 1px solid transparent;\n  background: none;\n  color: var(--muted);\n  font-size: 15px;\n  text-decoration: none;\n  white-space: nowrap;\n  cursor: pointer;\n}\n.app-nav a:hover, .app-nav button:hover { color: var(--accent); }\n.app-nav a[aria-current=\"page\"], .app-nav a.active, .app-nav button[aria-pressed=\"true\"] {\n  color: var(--ink);\n  border-bottom-color: var(--ink);\n}\n\n.app-actions { margin-left: auto; display: flex; align-items: center; gap: 12px; flex: none; }\n.app-meta { color: var(--muted); font-size: var(--text-sm); }\n\n.app-main {\n  width: 100%;\n  max-width: var(--column);\n  margin: 0 auto;\n  padding: 48px var(--gutter) 96px;\n}\n.app-main.wide { max-width: none; }\n\n.app-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 24px; padding-bottom: 24px; margin-bottom: 32px; border-bottom: 1px solid var(--line); }\n.app-head h1 { margin: 0; }\n.app-head p { margin: 8px 0 0; color: var(--muted); }\n\n.app-section { padding: 32px 0; border-top: 1px solid var(--line); }\n.app-section:first-child { border-top: 0; padding-top: 0; }\n\n.app-footer {\n  max-width: var(--column);\n  margin: 0 auto;\n  padding: 24px var(--gutter) 40px;\n  border-top: 1px solid var(--line);\n  color: var(--muted);\n  font-size: var(--text-sm);\n}\n\n/* ---------- Components ---------- */\n\n.muted { color: var(--muted); }\n.small { font-size: var(--text-sm); }\nhr.rule { border: 0; border-top: 1px solid var(--line); margin: 32px 0; }\n.sr-only, .sr { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }\n\n/* Buttons: ink on white or white on ink; accent on hover. Square corners. */\n.btn, .btn-primary, .btn-secondary {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  min-height: var(--control-height);\n  padding: 0 18px;\n  border: 1px solid var(--ink);\n  border-radius: 0;\n  background: var(--paper);\n  color: var(--ink);\n  font-size: 15px;\n  line-height: 1;\n  text-decoration: none;\n  white-space: nowrap;\n  cursor: pointer;\n  transition: background .2s var(--ease), color .2s var(--ease), border-color .2s var(--ease);\n}\n.btn:hover, .btn-secondary:hover { background: var(--ink); color: var(--paper); }\n.btn.primary, .btn-primary { background: var(--ink); color: var(--paper); }\n.btn.primary:hover, .btn-primary:hover { background: var(--accent); border-color: var(--accent); color: var(--paper); }\n.btn.ghost { border-color: transparent; }\n.btn.ghost:hover { background: none; color: var(--accent); }\n.btn.small { min-height: 32px; padding: 0 12px; font-size: var(--text-sm); }\n.btn:disabled, .btn[aria-disabled=\"true\"] { opacity: .45; cursor: default; pointer-events: none; }\n\n/* Inputs */\n.input, .field input, .field select, .field textarea {\n  width: 100%;\n  min-height: var(--control-height);\n  padding: 8px 12px;\n  border: 1px solid var(--line);\n  border-radius: 0;\n  background: var(--paper);\n  color: var(--ink);\n}\ntextarea.input, .field textarea { min-height: 96px; resize: vertical; }\n.input:hover, .field input:hover, .field select:hover, .field textarea:hover { border-color: var(--muted); }\n.input:focus, .field input:focus, .field select:focus, .field textarea:focus { border-color: var(--ink); outline: none; }\n.input:focus-visible, .field input:focus-visible, .field select:focus-visible, .field textarea:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }\n.field { display: grid; gap: 6px; margin-bottom: 16px; }\n.field > span, .field > label { font-size: var(--text-sm); color: var(--muted); }\n\n/* Tables */\n.table { width: 100%; border-collapse: collapse; font-size: 15px; }\n.table th { text-align: left; font-weight: 400; font-size: var(--text-sm); color: var(--muted); padding: 10px 12px 10px 0; border-bottom: 1px solid var(--ink); }\n.table td { padding: 12px 12px 12px 0; border-bottom: 1px solid var(--line); vertical-align: top; }\n.table tbody tr:hover td { background: none; color: var(--accent); }\n\n/* Notices: monochrome, a heavy ink rule on the left */\n.notice { padding: 12px 16px; border: 1px solid var(--line); border-left: 2px solid var(--ink); background: var(--paper); color: var(--ink); }\n.notice.muted { color: var(--muted); border-left-color: var(--line); }\n.notice + .notice { margin-top: 12px; }\n\n/* Empty states */\n.empty { padding: 64px 24px; text-align: center; color: var(--muted); border: 1px solid var(--line); }\n.empty h2, .empty h3 { color: var(--ink); }\n\n/* Lists of rows separated by hairlines */\n.rows { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--line); }\n.rows > li { padding: 14px 0; border-bottom: 1px solid var(--line); }\n\n/* ---------- Responsive ---------- */\n\n@media (max-width: 720px) {\n  :root { --gutter: 16px; }\n  .app-bar { flex-wrap: wrap; gap: 0 20px; padding-top: 14px; }\n  .app-wordmark { padding-bottom: 2px; }\n  .app-actions { margin-left: auto; }\n  .app-nav { order: 3; width: 100%; gap: 20px; }\n  .app-nav a, .app-nav button { padding: 12px 0 11px; }\n  .app-main { padding-top: 32px; padding-bottom: 64px; }\n  .app-head { flex-direction: column; align-items: flex-start; }\n}\n\n/* ---------- Motion ---------- */\n\n.motion-paused *, .motion-paused *::after { animation: none !important; transition: none !important; scroll-behavior: auto !important; }\n@media (prefers-reduced-motion: reduce) {\n  html { scroll-behavior: auto; }\n  *, *::after { animation: none !important; transition: none !important; }\n}\n";
